from pathlib import Path
import json
R=Path(__file__).resolve().parents[1]
pages=[]
def page(s,bars,title,intro,rows):
 blocks=[]
 for n,(label,kind,text,ev) in enumerate(rows,1):
  blocks.append(dict(id=f'{s}-B{n:02}',label=label,kind=kind,text=text,meaning_ids=[],evidence=[dict(uid=u,quote=q) for u,q in ev]))
 pages.append(dict(segment=s,bars=bars,title=title,intro=intro,blocks=blocks,decisions=[]))
page('S02','4–16','贴近了，仍把声音放轻','摇晃先把身体托住，歌声才慢慢浮出来。',[
('把重量交给水','observation','波浪像心跳，也像水流自己在呼吸。可以把身体的重量交给这片深不可测、温热的水：陆地上的病痛、琐事和沉重被留在外面，连先前的惊悸也慢慢平下来。这份疲倦中的安宁，像是偷来的。', [('SRC-gflash-int-3-U03','把整个身体的重量完全交托给身下那片深不可测、温热且规律起伏的水体。'),('SRC-gflash-web-3-U02','水波的起伏抚平了内心的惊悸。'),('SRC-gflash-int-1-U02','卸下戒备的疲惫感，夹杂着“偷来的安宁”。')]),
('只让身边的人听见','facets','像午后暖金色的斜光里，两个人肩并肩坐在摇晃的船舱。肩膀贴着肩膀，呼吸、语调和肢体的触碰挨得很近，声音只需彼此听见；再响一点，仿佛就会惊碎眼前的幻觉。这份私密容不下第三个人。两条声音也在互相回应，各自还留着一点空间。',[('SRC-gflash-int-2-U03','下午斜照在水面的暖金光线，两个人肩并肩坐在摇晃的船舱里。'),('SRC-gflash-int-1-U04','两个紧挨在一起的人在耳语'),('SRC-gflash-int-3-U05','呼吸和语调完全同频，亲密到容不下第三者。'),('SRC-gpt6w-web-3-U04','它们靠得很近，却又各自保留了一点空间。')]),
('微醺的温度','facets','这份温存有黄昏的倦意和微醺，成熟得近乎颓废。像夏末傍晚潮湿、温热的微风裹在皮肤上，甚至有些黏稠；两个人的呼吸和体温贴得化不开。',[('SRC-gflash-int-3-U05','黄昏时的倦意和微醺感'),('SRC-gflash-int-3-U05','潮湿、温热的微风，裹在皮肤上甚至有些黏稠。'),('SRC-gflash-web-1-U03','成熟到近乎颓废'),('SRC-gflash-web-1-U03','两个人的呼吸和体温贴得极近，甚至有些黏稠和化不开。')]),
('终于可以放心','alternatives','也可以听成一个惯于自我克制的人，终于来到不用时刻警惕的地方。和熟悉的人待着，不必找话题，也不担心沉默；对方偶尔望你一眼，就已经很满足。温柔里有愿意信任、愿意靠近的意思，满足了，仍舍不得就这样停住。',[('SRC-gpt6w-int-3-U03','更像是一个平时习惯克制自己的人，终于来到一个不必时刻保持警惕的地方。'),('SRC-gpt6w-int-3-U03','对方偶尔望你一眼，你心里就已经很满足。')]),
('仍然不敢用力','alternatives','另一种亲近，还留着警觉。像久别后再见重要的人，仍能自然笑谈，却已知道这样的时刻并非取之不尽；又像共同生活过后，一个普通晚上忽然想到：“这个人在这里，真好。”手轻轻抚着对方的脸，脑中却闪过它不会永远如此的念头。手掌托着珍贵、易碎的东西，靠近，也不肯把全部重量压上去。',[('SRC-gpt56w-int-2-U03','但你不会再像年轻时那样误以为这种时刻取之不尽。'),('SRC-gpt56w-int-r1-U03','这个人在这里，真好。'),('SRC-gpt56w-int-r1-U03','像伸手抚摸一个人的脸，同时脑中极快地闪过一个念头：'),('SRC-gpt56w-int-3-U03','手掌托着很珍贵、很容易碎的东西时的温柔'),('SRC-gpt56w-web-r1-U03','我很靠近你，但我还不肯把全部重量压上去。')]),
('还在眼前，已经舍不得','facets','水一直流，时间一直走。眼前越好，越想让它慢一点：黄昏还在好看，心里已经难过它快没了；和喜欢的人坐着，内心却有个声音说“这种时刻不多了”。像靠在船舷上望远处，不敢看得太用力，怕把这片刻看碎。此时还没有失去，幸福已经生出了依恋。',[('SRC-gflash-int-1-U04','因为水波的晃动是不可逆的——水在流，时间在走。'),('SRC-muse-int-1-U03','这种时刻不多了'),('SRC-muse-int-1-U03','像靠在船舷上，眼睛看着远处，不敢看太用力，怕把这片刻看碎了。')]),
('也可能是一个人的两种声音','alternatives','双声也可以听成一个人内心的两种声音互相依偎。明明像两个人在唱，却又像一个人分饰两角，怕吵醒水面，甜里面有孤独。一个人也可以安静拥有这份感觉；夜里走熟悉的路，脚步很稳，脑中却有复杂的期待和重量。',[('SRC-gpt56w-web-2-U03','一个人内心两种声音互相依偎'),('SRC-muse-web-1-U03','明明是两个人唱，却像一个人分饰两角，怕吵醒水面。'),('SRC-gpt56w-int-r1-U02','比如一个人夜里走很熟悉的路，脚步非常规律，但脑中想着的东西一点也不平静。')]),
('同一尾音的三次变化','sequence','相似的尾音回来，底下的水波和光影却在变。同一句话说三遍，可以听成：第一次是安慰，第二次是犹豫，第三次已经有点疼。也像“我们在这里”变成“我们还在这里吗”，最后成了“恐怕待不久了”。甜蜜的确认里，带着一根温柔的刺。',[('SRC-muse-web-3-U03','第一次是安慰，第二次是犹豫，第三次已经有点疼了。'),('SRC-muse-web-1-U03','第一次是“我们在这里”，第二次是“我们还在这里吗”，第三次已经有点“恐怕待不久了”。'),('SRC-gflash-web-3-U03','温柔的刺')]),
('同一句温柔，也可以是怀念','alternatives','另有一种带着过去的听法：你知道回不去了，却也不想回去，只觉得“有过真好，但有过就意味着没了”。暖暖的长旋律像有人轻轻摸你的头，底下不停的摇晃又提醒你，这是水上托不住的东西。不哭，眼眶却是热的；也像笑着哄最爱的人，心知留不住，仍要把这句唱完。',[('SRC-muse-int-2-U03','有过真好，但有过就意味着没了'),('SRC-muse-int-2-U03','像有人轻轻摸你的头'),('SRC-muse-int-3-U03','眼眶有点热，但还是要笑着把这句唱完')]),
('又暖又凉的夜水','alternatives','水也未必是明亮、清澈的：可以想成夏夜深绿近黑、有点浑、有点凉的水，又怕又爽。一种“幸福的害怕”，像夜里独自清醒地想念，又暖又凉。这里的害怕本身，也带着一点甜。',[('SRC-muse-web-2-U03','是夏夜深绿近黑的水，有点浑，有点凉。'),('SRC-muse-web-2-U03','幸福的害怕'),('SRC-muse-web-2-U03','夜里一个人很清醒的想念，又暖又凉')]),
('向上唱，反而放轻','observation','旋律刚往高处伸，声音反而收轻。千言万语涌上来，开口第一句却轻得像叹息，有一点近乡情怯。怕热情太明显，也怕一个过重的动作破坏气氛。唱得更高，并不急着把感情全部放出来。',[('SRC-gflash-web-3-U03','千言万语涌上心头，开口的第一句话却轻得像叹息。'),('SRC-gflash-web-3-U03','近乡情怯'),('SRC-gpt6w-web-1-U05','甚至有一点怕自己的热情太明显。')]),
('涌起，再松一口气','sequence','几个乐句本来可以停下，却还想把同一种感觉说得更充分。到后半，呼吸收紧，情绪往上涌；随后又像轻轻呼出一口气。短暂落稳，可以像终于得到回应的一次相视；声音很快又漂起来，心事还没有全说尽。',[('SRC-gpt6w-web-3-U04','本来已经可以停下，却又忍不住接着说。'),('SRC-gpt6w-web-1-U05','它又像轻轻呼出一口气，回到柔和之中。'),('SRC-luna-web-2-U04','那一刻可以像一次终于得到回应的相视，但声音很快又漂起来，没有把心事彻底说死。')])])
page('S04','24–34','同一首歌，为什么越说越多','熟悉的歌回来，装饰更密，声音更亮、更丰满。',[
('因为舍不得略过细节','alternatives','像一个人把同一段回忆越说越细，越说越舍不得停。刚刚经历的快乐，回想时不自觉又添了一点美好；同一句话说第二遍，多了依恋。也可以像努力让自己再相信一次，想把刚才的亲密重新留住。',[('SRC-muse-web-2-U03','像一个人把同一段回忆越说越细，越说越舍不得停。'),('SRC-gpt6w-web-2-U06','会不自觉地把它想得更加美好。'),('SRC-muse-int-3-U03','像是努力想让自己再相信一次。')]),
('因为开始怕它结束','alternatives','也可能是聊得越开心，越怕冷场。语速变快，笑里加料，身体向前倾，晃的幅度也大了；手指忍不住多摸两下，想多留一点。享受开始变成轻微的焦虑：更甜、更满，底下却有点喘。到了末尾，连摇晃都慢下来，像不想让谈话结束。',[('SRC-muse-int-1-U04','像聊天聊得很开心，你开始语速变快、笑里加料，怕冷场。'),('SRC-muse-int-1-U04','享受变成了轻微的焦虑。'),('SRC-muse-int-1-U04','音乐听起来更甜更满，但底下有点喘。'),('SRC-luna-web-2-U05','像不想让这段谈话结束。')]),
('因为最重要的话还没说完','alternatives','一句不够，再说一遍，又觉得不够准确，换个方式重说。“我很喜欢这一刻”，变成“你真的明白这一刻对我意味着什么吗？”也像原本微笑着听的人，不知不觉坐直了，越来越多话要说。越投入，越难保持先前优雅的距离；心满意足才刚来，又觉得还差一点。',[('SRC-gpt56w-int-3-U04','本来一句话已经够了，却忍不住再说一遍；第二遍又觉得还不够准确，于是换一种方式再说。'),('SRC-gpt56w-int-3-U04','你真的明白这一刻对我意味着什么吗？'),('SRC-gpt6w-int-3-U04','后来不知不觉坐直了身体，有越来越多的话想说。')]),
('因为这件事其实没有过去','alternatives','还可以听成一个人讲往事：起初还能微笑，讲着讲着语速变了，细节越添越多。旁人才听出来，原来这件事根本没有过去。自己也开始追问：为什么到现在还这样在意？它对我究竟意味着什么？外表仍然漂亮，里面已经不平静。',[('SRC-gpt56w-int-2-U04','刚开始还能微笑着讲，讲着讲着语速变了，开始补充越来越多细节。'),('SRC-gpt56w-int-2-U04','原来这件事根本没有过去。')]),
('想要的不止是此刻','facets','原本轻轻握着的手，不知不觉握紧了，身体先泄露自己还没想清的害怕。想再近一点、再多一点，想知道这份亲近究竟有多深，能不能一直持续。甚至从凝视变成伸手抓住对方：不能只静静珍惜，我需要你回应。爱更充沛，确信更强，也因为太想确信而更不安全；感情超过了原先准备好的容器。',[('SRC-gpt6w-int-2-U04','后来不自觉地握得更紧。'),('SRC-gpt56w-int-3-U05','我需要它回应我。'),('SRC-gpt56w-int-3-U05','感情开始超过一个人原先准备好的容器')]),
('幸福里绕起的念头','facets','“我很爱这个人”之后，又问“为什么这么爱”，再想到失去，接着责备自己为什么偏偏在幸福时想到失去。越想安静，越安静不下来：一面想维持优雅、克制和完整，一面又撑不住。认真开始带来要求——确定、回答、永远——而这些要求还没有得到保证。',[('SRC-gpt56w-int-r1-U04','为什么偏偏在幸福的时候想到失去？'),('SRC-gpt56w-int-r1-U04','越想安静，越安静不下来'),('SRC-gpt56w-web-3-U05','确定'),('SRC-gpt6w-int-1-U05','它像一种想得到保证的渴望，而不是已经得到保证的满足。')]),
('花纹也有触感','facets','那些装饰可以像船桨提起后，水珠拉成细丝，在残阳下反光滑落；也可以像飞溅的水珠、摇碎的波光，或细碎的星光反射。光斑晃得几乎睁不开眼，心动也被放大了。沉醉里，仿佛偶然漏掉一拍心跳。',[('SRC-gflash-int-3-U05','水珠拉成细丝、在残阳下反光滑落的质感。'),('SRC-gflash-web-2-U03','水面上摇碎的波光，以及由于沉醉而偶然漏掉的一拍心跳。'),('SRC-gflash-int-2-U03','仿佛水面折射的光斑突然晃得人睁不开眼')]),
('到了喉咙口','facets','高处的长颤音，像最深的情意到了喉咙口，先颤抖、哽咽了一下。上面的歌声悬着，下面的水波还推着它走。也可以想成越想用力抱紧，水面反而越颠簸，船舱里的平衡越脆弱；耀眼的颤动像最后一道夕阳金光，最炽热的时候，也让人想到日落。',[('SRC-gflash-int-1-U07','却在喉咙口颤抖、哽咽'),('SRC-gflash-int-1-U07','右手在高处悬停，左手的水波却推着你不得不往前走。'),('SRC-gflash-int-3-U05','船舱内的平衡就越脆弱。'),('SRC-gflash-web-1-U03','炽热到了顶点，也意味着日落的降临。')]),
('收束了，心里仍有问句','observation','接近高处，可以像已经走到对方面前，却在最后一句话出口前又停住。情绪已经打开，随后放慢、退开，话的余响还在，人先安静下来。音乐在这里收束，并不妨碍心里仍留着“话没有说完”的感觉。',[('SRC-gpt56w-web-2-U05','我明明已经走到你面前，却在最后一句话出口之前又停住了'),('SRC-luna-int-3-U04','仿佛刚说出口的话在空气里回荡，人却安静下来。'),('SRC-luna-web-3-U05','话没说完')]),
('提前怀念，还未实现','alternatives','酸楚也可能指向不同的东西。一种像快乐旅行途中，忽然知道几年以后自己一定会怀念今天：快乐还在，却多了一点酸。另一种舍不得的，是一份尚未实现、已经觉得珍贵的可能。知道单靠愿望留不住，仍然想靠近。',[('SRC-gpt6w-int-3-U05','几年以后自己一定会怀念今天。'),('SRC-luna-int-1-U03','舍不得一份尚未实现、却已经觉得珍贵的可能。'),('SRC-gpt6w-int-3-U05','不愿意因为意识到脆弱，就放弃亲近美好的东西。')])])
page('S07','51–61','沉默、回想，或沉进感觉里','歌声重新走过相似的地方，更丰满，伴奏也更密；声音会收轻，再推起来，迫切感并不只来自音量。',[
('深谈之后，语言暂时跟不上','alternatives','前面的渴望已经说得太多，现在反而不知道还能说什么。像一次很深入的谈话后，两个人都沉默下来，并不尴尬，只是语言暂时跟不上感受。有一点心理上的失重，既不是痛苦，也还没有得到解脱。变安静了，感受并没有变浅。',[('SRC-gpt56w-int-2-U06','前面的渴望已经说得太多，现在反而暂时不知道还能说什么。'),('SRC-gpt56w-int-2-U06','而是语言已经暂时跟不上感受。'),('SRC-gpt56w-int-2-U06','所以它变得更安静，却并没有变浅。')]),
('谈话已经过去，脑中还在重放','alternatives','另一种听法，心里一直没能停下来。“可是如果这一切终究会过去呢？”像深夜已经决定睡觉，脑子又开始播放白天的谈话；没有新事实，却不停换个角度重想。表面还从容漂亮，意识已经重新和自己争论。',[('SRC-gpt56w-int-3-U07','可是如果这一切终究会过去呢？'),('SRC-gpt56w-int-3-U07','你并没有新的事实可想，却不停从另一个角度重新想它。'),('SRC-gpt56w-int-3-U07','意识重新开始和自己争论。')]),
('沉迷于自己正在感觉','alternatives','也可以是关注的对象变了：原来想着某个人、某件事，现在开始沉迷于“自己正在感觉”。气味、身体感觉、幻想、遗憾和快感混在一起，有一点情色性的暖意。越舒服，越失去方向；越沉进去，越难退开一点来控制它。沉醉和不安一起增加，明知被卷入，暂时仍不想出来。',[('SRC-gpt56w-web-2-U06','原来是在想着某个人、某件事；现在却开始沉迷于“自己正在感觉”这件事。'),('SRC-gpt56w-web-2-U06','气味、身体感觉、幻想、遗憾、快感混在一起。'),('SRC-gpt56w-web-2-U06','它有一点情色性的暖意'),('SRC-gpt56w-web-r1-U06','你明知道自己在被它卷进去，却暂时不想出来。')]),
('在乎得再深，也留不住时间','facets','有一份无能为力：再爱一个人，也不能保证他永远存在；知道此刻完美，仍不能让此刻停住。美还在，什么都还很好，时间却正在经过。这比一切已经毁掉时更难痛快哭出来。眼前的情绪仿佛比具体的人和事还大，伸向时间、人与人的距离，以及幸福为什么总和失去挨得很近。',[('SRC-gpt56w-int-r1-U06','我可以非常爱一个人，却不能保证他永远存在。'),('SRC-gpt56w-int-r1-U06','什么都还很好，可你已经听见时间正在经过。'),('SRC-gpt56w-int-2-U06','自己眼前的情绪，其实比那个具体的人、具体的事情还要大。')]),
('人很近，仍有独自承担的部分','facets','即使被爱，也有一些感受无法完全交给对方。亲密的人可能就在眼前，仍觉得不能完全抵达他；内心的一部分，只能由自己承担。想改变眼前的处境，又怕改变把已经拥有的东西带走。温柔、安全感和一点漂泊，可以同时在。',[('SRC-gpt56w-web-3-U06','即使被爱，我仍不能彻底逃出作为一个人的孤单。'),('SRC-gpt6w-web-3-U09','甚至可能就在眼前；可你仍觉得自己无法完全抵达他或她。'),('SRC-gpt6w-web-1-U10','既希望生活改变，又害怕改变会带走自己已经拥有的东西。')]),
('一句平时藏起来的真话','alternatives','也像轻松交谈中，忽然说出一句简单、很真心的话。两个人没有立刻接上，因为都知道它的分量。想靠近，又因为太认真而羞怯、犹豫。此刻肯让对方看见脆弱：“你对我如此重要”，既让人幸福，也有点害怕。',[('SRC-gpt6w-int-3-U06','说了一句很简单、却很真心的话。'),('SRC-gpt6w-int-3-U06','因为他们知道，这句话的分量比表面上重得多。'),('SRC-gpt6w-int-3-U06','你对我如此重要，这件事让我既幸福，又有些害怕')]),
('从容越来越难维持','facets','愿望一直在推：本想把心事藏好，反复升温后却发现藏不住；本想安静地与你相处，感情太深，又不能只安静相处。想更靠近、更深入，压住的心事也成了动力。坦白中有兴奋和陶醉，也有这样强的时刻无法持续的疼；说出来，只是承认自己有多在乎。',[('SRC-gpt6w-web-2-U07','逐渐发现自己根本藏不住。'),('SRC-gpt6w-web-3-U09','我希望就这样安静地与你相处，但我的感情太深了，已经不允许我只是安静地相处。'),('SRC-luna-int-2-U05','同时也有疼痛，因为这样强烈的时刻很难一直维持。')]),
('坐不住，想找一个去处','alternatives','还可以像思绪散了，一个念头接一个念头，试了几个方向都不对。久坐后起来走走，半夜睡不着翻身，想找回刚才的感觉却找不到：暖意还在，光暗了一点，水也凉了一点。慢慢变得烦躁、脚步细碎，心里非要去一个地方。',[('SRC-muse-int-1-U05','一个念头接一个念头，试了几个方向都不对。'),('SRC-muse-int-1-U05','有点像久坐之后起来走走，又像半夜睡不着翻身'),('SRC-muse-int-1-U05','刚才的暖意还在，但光线暗了一点，水变凉了。')]),
('想活得更热一些','alternatives','另有一种更炽热的听法：纯净的回忆转成对活着的饥渴。可以想成“身体在衰竭，心依然跳得滚烫”的主观自白；情欲、执念和对生的眷恋，像潮水从心底翻上来。这是一种不甘，不必替它安上作曲者某一天的病况。',[('SRC-gflash-int-1-U09','随后转化为对“活着”的强烈饥渴。'),('SRC-gflash-int-1-U11','我的身体在衰竭，但我的心依然能跳得如此滚烫。'),('SRC-gflash-int-1-U11','情欲、执念与对生的眷恋像潮水般从心底翻涌而上。')]),
('亮起来，仍然待不稳','alternatives','也可能一边被新鲜感吸引，一边回头确认自己是否走远了。好不容易想象出一个温暖的地方，赶紧住进去，却总要起来检查门锁。想享受当下，脑子又飘到旧事和未来：渴望幸福，也不相信它会留下。',[('SRC-luna-int-3-U06','像一边被新鲜感吸引，一边又忍不住回头确认自己是不是走远了。'),('SRC-muse-web-2-U04','好不容易幻想出一个温暖的地方，赶紧搬进去，但心里不踏实，总要起来检查门锁。'),('SRC-muse-web-1-U04','一会儿想起旧事，一会儿担心未来。')])])
(R/'drafts'/'pilots_editor.json').write_text(json.dumps({'pages':pages,'method_notes':['主编辑回读完整Pool后写作；与Flash原始生成结果分别保留，未冒充模型响应。','待独立语义复核。']},ensure_ascii=False,indent=2),encoding='utf-8')
print('editor pilot draft',[(p['segment'],len(''.join(b['text'] for b in p['blocks']))) for p in pages])
